import { readdirSync, existsSync, writeFileSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

// `--check` writes nothing and exits 1 when a committed generated file (index.ts, component-names.ts, globals.ts) is stale.
const check = process.argv.includes("--check");
const stale = [];
const emit = (file, content) => {
  if (!check) return writeFileSync(file, content);
  const current = existsSync(file) ? readFileSync(file, "utf8").replaceAll("\r\n", "\n") : "";
  if (current !== content) stale.push(file.slice(root.length + 1));
};

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "src");
const components = existsSync(join(root, "components"))
  ? readdirSync(join(root, "components"), { withFileTypes: true })
      .filter((d) => d.isDirectory() && existsSync(join(root, "components", d.name, "index.ts")))
      .map((d) => d.name)
      .sort()
  : [];
const composables = existsSync(join(root, "composables"))
  ? readdirSync(join(root, "composables"))
      .filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"))
      .map((f) => f.slice(0, -3))
      .sort()
  : [];

// A composable's exports are public unless marked `@internal`: in the JSDoc right before the export, or with a first line
// of `// @internal` for the whole file. The components share internal helpers (useSize, useDetails, useFieldControl) that are not
// part of the package's API, so they are named here one by one instead of with `export *`.
const exportLine =
  /(\/\*\*(?:(?!\*\/)[\s\S])*\*\/\s*)?^export\s+(?:declare\s+)?(?:async\s+)?(function|const|let|class|interface|type|enum)\s+([A-Za-z0-9_$]+)/gm;
function composableExports(name) {
  const source = readFileSync(join(root, "composables", `${name}.ts`), "utf8").replaceAll("\r\n", "\n");
  if (source.startsWith("// @internal")) return [];
  if (/^export\s*(\{|\*)/m.test(source))
    throw new Error(
      `composables/${name}.ts re-exports; export each name where it is declared so gen-index can list it`,
    );
  const values = [];
  const types = [];
  for (const m of source.matchAll(exportLine)) {
    if (m[1]?.includes("@internal")) continue;
    (m[2] === "interface" || m[2] === "type" ? types : values).push(m[3]);
  }
  const from = `"./composables/${name}.js"`;
  // Written as Prettier would (print width 120), so the generated file passes `format:check`.
  const line = (lead, names) => {
    const one = `${lead} { ${names.join(", ")} } from ${from};`;
    return one.length <= 120 ? one : `${lead} {\n${names.map((n) => `  ${n},\n`).join("")}} from ${from};`;
  };
  return [...(values.length ? [line("export", values)] : []), ...(types.length ? [line("export type", types)] : [])];
}

const lines = [
  "// Generated by scripts/gen-index.mjs. Do not edit.",
  'export { createEos, themeCss } from "./plugin.js";',
  'export type { Eos, EosOptions } from "./plugin.js";',
  'export { useConfig, useMessages, useIconResolver, usePortalTarget, CONFIG_KEY } from "./config.js";',
  'export type { EosConfig, MessageValue, PluralMessage, Translate } from "./config.js";',
  'export { defaultMessages } from "./messages.js";',
  'export type { MessageKey } from "./messages.js";',
  'export { phosphor } from "./icons/phosphor.js";',
  'export type { IconName, IconMarkup } from "./icons/phosphor.js";',
  'export { iconNames } from "./icons/types.js";',
  'export type { IconProp, IconSource, IconsConfig, IconContext } from "./icons/types.js";',
  'export type { ResolvedIcon } from "./config.js";',
  'export { defineTheme } from "@eos-ui/tokens";',
  'export type { Theme, ThemeInput } from "@eos-ui/tokens";',
  ...composables.flatMap(composableExports),
  ...components.map((c) => `export * from "./components/${c}/index.js";`),
  "",
];
emit(join(root, "index.ts"), lines.join("\n"));

const names = components
  .flatMap((c) =>
    [
      ...readFileSync(join(root, "components", c, "index.ts"), "utf8").matchAll(
        /export \{ default as (E[A-Za-z0-9]+) \}/g,
      ),
    ].map((m) => m[1]),
  )
  .sort();
const header = "// Generated by scripts/gen-index.mjs. Do not edit.\n";
emit(
  join(root, "component-names.ts"),
  `${header}export const componentNames: ReadonlySet<string> = new Set([\n${names.map((n) => `  "${n}",\n`).join("")}]);\n`,
);
// Gives Volar and vue-tsc the global component types (<EButton> in a template after `app.component` registration).
// Opt-in, as `@eos-ui/vue/globals`: `createEos()` registers no components, so declaring them for every app would let a
// missing import pass the type check and fail at run time. `$e` is declared in plugin.ts, since the plugin always sets it.
emit(
  join(root, "globals.ts"),
  `${header}// Opt-in types for components you register globally with \`app.component\`. Load them with
// \`import type {} from "@eos-ui/vue/globals"\` or \`"types": ["@eos-ui/vue/globals"]\` in tsconfig.json.
import type * as Library from "./index.js";

declare module "vue" {
  interface GlobalComponents {
${names.map((n) => `    ${n}: typeof Library.${n};\n`).join("")}  }
}

export {};
`,
);
if (check) {
  if (stale.length) {
    console.error(
      `Generated files are stale: ${stale.join(", ")}. Run \`pnpm --filter @eos-ui/vue prepare:gen\` and commit the result.`,
    );
    process.exit(1);
  }
  console.log("generated files are up to date");
} else console.log(`index.ts: ${components.length} components, ${composables.length} composables`);
